package org.brightstats.stats;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import com.google.gson.*;
import org.apache.commons.math3.distribution.NormalDistribution;

public final class SimulationChecks {
    static int checks;static void require(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    static SemModel.Model meanModel(double value){return new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of(new SemModel.Parameter("Mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),value,1)));}
    static SemSimulation.Design design(SemModel.Model model,int[] sizes,int repetitions,List<SemSimulation.Target> targets,SemSimulation.Distribution distribution,SemSimulation.Missingness missing,double rate,SemSimulation.Uncertainty uncertainty,int workers){return new SemSimulation.Design(model,null,sizes,repetitions,targets,distribution,7,missing,rate,0,1,uncertainty,.05,.8,5533881,workers,true,FimlSem.Options.defaults());}
    public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);Files.createDirectories(out);var model=meanModel(.35);var targets=List.of(new SemSimulation.Target("Mean",0));var plan=design(model,new int[]{30,80},1000,targets,SemSimulation.Distribution.NORMAL,SemSimulation.Missingness.NONE,0,SemSimulation.Uncertainty.MODEL,2);AtomicInteger progress=new AtomicInteger();var parallel=SemSimulation.run(plan,step->{if(step!=progress.incrementAndGet())throw new AssertionError("Completed-attempt progress is not genuine and monotonic");});var sequential=SemSimulation.run(design(model,new int[]{30,80},1000,targets,SemSimulation.Distribution.NORMAL,SemSimulation.Missingness.NONE,0,SemSimulation.Uncertainty.MODEL,1),null);require(parallel.replicates().equals(sequential.replicates())&&parallel.replicateResultSha256().equals(sequential.replicateResultSha256()),"Worker count does not change seeds, results, failures or order");require(progress.get()==2000&&parallel.completedAttempts()==2000,"Exact attempt accounting");NormalDistribution normal=new NormalDistribution();for(var row:parallel.summaries()){double z=normal.inverseCumulativeProbability(.975),delta=.35*Math.sqrt(row.sampleSize()),theory=normal.cumulativeProbability(delta-z)+normal.cumulativeProbability(-delta-z);require(row.failures()==0&&row.tested()==1000,"Known-variance mean fits all regular");require(Math.abs(row.conditionalPower()-theory)<4*Math.sqrt(theory*(1-theory)/1000)+.002,"Analytic normal-test power within Monte Carlo uncertainty");require(Math.abs(row.conditionalCoverage()-.95)<.035,"Nominal exact-normal interval coverage");require(Math.abs(row.meanStandardError()-1/Math.sqrt(row.sampleSize()))<1e-7,"Known-variance standard error");require(Math.abs(row.bias())<.035,"Mean estimator bias within Monte Carlo error");}require(parallel.recommendations().getFirst().firstTestedNPointThreshold()==80,"Recommendation is a tested N, never extrapolated");
        var mcar=SemSimulation.run(design(FimlChecks.saturated(),new int[]{80},40,List.of(new SemSimulation.Target("Mean X",0)),SemSimulation.Distribution.NORMAL,SemSimulation.Missingness.MCAR,.25,SemSimulation.Uncertainty.SANDWICH,2),null);require(mcar.summaries().getFirst().meanMissingFraction()>.20&&mcar.summaries().getFirst().meanMissingFraction()<.30,"Actual MCAR masking rate");var mar=SemSimulation.run(design(FimlChecks.saturated(),new int[]{80},40,List.of(new SemSimulation.Target("Mean X",0)),SemSimulation.Distribution.NORMAL,SemSimulation.Missingness.MAR,.35,SemSimulation.Uncertainty.SANDWICH,2),null);require(mar.replicates().stream().allMatch(t->t.informativeRows()==80&&t.missingCells()<=80),"MAR driver stays observed and no source rows disappear");var stress=new ArrayList<SemSimulation.Result>();for(var distribution:List.of(SemSimulation.Distribution.STUDENT_T,SemSimulation.Distribution.SKEWED_EXPONENTIAL)){var result=SemSimulation.run(design(model,new int[]{50},40,targets,distribution,SemSimulation.Missingness.NONE,0,SemSimulation.Uncertainty.SANDWICH,2),null);require(result.summaries().getFirst().tested()>=35,"Non-normal stress scenario performs genuine complete fits");stress.add(result);}var sparse=SemSimulation.run(design(model,new int[]{20},80,targets,SemSimulation.Distribution.NORMAL,SemSimulation.Missingness.MCAR,.8,SemSimulation.Uncertainty.MODEL,2),null);require(sparse.summaries().getFirst().failures()>0&&sparse.completedAttempts()==80,"Failed attempts are retained without replacement");require(sparse.summaries().getFirst().attemptLevelDetectionRate()<=sparse.summaries().getFirst().conditionalPower(),"Operational detection includes failed attempts");Thread.currentThread().interrupt();try{SemSimulation.run(plan,null);throw new AssertionError("Study cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject record=new JsonObject();record.add("normal",gson.toJsonTree(parallel));record.add("mcar",gson.toJsonTree(mcar));record.add("mar",gson.toJsonTree(mar));record.add("nonNormal",gson.toJsonTree(stress));record.add("sparse",gson.toJsonTree(sparse));record.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),gson.toJson(record));System.out.println("Simulation checks: "+checks);}
}
